spots = json.load(io.open(P, encoding='utf-8')); ledger = json.load(io.open(L, encoding='utf-8'))


def norm(s):
    s = unicodedata.normalize('NFKC', s or '')
    s = re.sub(r'[\s・\-ー〜~()（）「」『』【】]', '', s)
    return s.lower()


def core(nm):
    return norm(re.sub(r'[(（].*?[)）]', '', nm))


def geocode(q):
    cands = [q, re.sub(r'(\d+)[-−ー](\d+)[-−ー]\d+.*$', r'\1-\2', q), re.sub(r'\d.*$', '', q)]
    for n, c in enumerate(dict.fromkeys(cands)):
        if n:
            time.sleep(10)
        u = 'https://www.geocoding.jp/api/?q=' + urllib.parse.quote(c)
        try:
            x = urllib.request.urlopen(urllib.request.Request(u, headers={'User-Agent': 'Mozilla/5.0'}), timeout=20).read().decode('utf-8', 'ignore')
        except Exception as e:
            print('  err', e); continue
        la = re.search(r'<lat>([\d.]+)</lat>', x); ln = re.search(r'<lng>([\d.]+)</lng>', x)
        if la and ln and float(la.group(1)) > 1:
            return float(la.group(1)), float(ln.group(1)), n
    return None, None, -1


def km(a, b, c, d):
    return math.hypot((a - c) * 111, (b - d) * 111 * math.cos(math.radians(a)))


ex = [(core(s['name']), s) for s in spots]
added, dup, ng = [], [], []
for (nm, ad, pref, city, area, gen, cat, kids, pts, stay, day, acc, code) in C:
    c = core(nm)
    hit = next((s for k, s in ex if k and (c in k or k in c) and min(len(c), len(k)) >= 3), None)
    if hit:
        dup.append((nm, hit['name'])); continue
    lat, lng, lvl = geocode(ad); time.sleep(10)
    if not lat:
        ng.append(nm); print('NG', nm); continue
    near = [s for s in spots if s.get('lat') and km(lat, lng, s['lat'], s['lng']) < 0.15
            and len(set(c) & set(core(s['name']))) >= max(3, len(c) // 3)]
    if near:
        dup.append((nm, near[0]['name'] + '(近傍)')); continue
    sid = 'sn' + hashlib.md5(nm.encode('utf-8')).hexdigest()[:10]
    k = {'stroller': None, 'diaper': None, 'tatami': None, 'kidsChair': None, 'kidsMenu': None, 'serveMin': None, 'noise': None}
    k.update(kids)
    kind = {'onsen': '宿・温泉', 'play': '施設', 'gourmet': 'お店'}[cat]
    rec = {'id': sid, 'name': nm, 'area': area, 'city': city, 'pref': pref, 'genre': gen, 'lat': lat, 'lng': lng, 'address': ad,
           'visited': None, 'with': 'family', 'category': cat, 'wish': True, 'kids': k,
           'points': pts + ['⚠ 未訪問のため設備・料金は未確認(行ったら更新します)'],
           'memo': '行ってみたい%sとして登録。%s。当方は未訪問で、設備や料金は未確認です。' % (kind, '、'.join(p.replace('⚠ ', '') for p in pts[:2])),
           'verdict': '未訪問の%s。%s。設備・料金・営業日は変わることがあるので、行く前に公式で確認してください。' % (kind, '・'.join(p.replace('⚠ ', '') for p in pts)),
           'video': {'youtube': None, 'tiktok': None, 'instagram': None}, 'thumb': None, 'photos': None,
           'source': 'sns:' + acc, 'added': TODAY}
    if stay is not None: rec['stay'] = stay
    if day is not None: rec['dayUse'] = day
    if lvl > 0: rec['geo_approx'] = True
    spots.append(rec); ex.append((c, rec)); added.append(sid)
    ledger.append({'name': nm, 'address': ad, 'feats': pts, 'src': 'instagram:@' + acc, 'post': 'https://www.instagram.com/p/%s/' % code,
                   'posted_year': '2025-2026', 'map_match': sid, 'imported': TODAY})
    print('OK', nm, lat, lng, '' if lvl == 0 else '(住所を丸めて取得)')

